import 'supabase_service.dart';
class SafetyService{final db=SupabaseService.client;String get uid=>db.auth.currentUser!.id;Future<void>block(String id)async=>db.from('user_blocks').upsert({'blocker_id':uid,'blocked_id':id});Future<void>unblock(String id)async=>db.from('user_blocks').delete().match({'blocker_id':uid,'blocked_id':id});Future<void>report({String? reportedUserId,String? contentType,String? contentId,required String reason,String details=''})async=>db.from('safety_reports').insert({'reporter_id':uid,'reported_user_id':reportedUserId,'content_type':contentType,'content_id':contentId,'reason':reason,'details':details});Future<void>requestVerification(String type,String note)async=>db.rpc('submit_verification',params:{'p_document_type':type,'p_note':note.trim()});Future<List<Map<String,dynamic>>> myVerification()async=>db.from('verification_requests').select().eq('user_id',uid).order('created_at',ascending:false);}
